318	// appendFilenameExtension adds a MIME-derived extension when the resolved
319	// filename has no usable extension. Some image hosts use opaque path segments
320	// that look like extensions, even though the response Content-Type is the
321	// only reliable source for the file type.
322	func appendFilenameExtension(filename, contentType string) string {
323		mediaType, _, err := mime.ParseMediaType(contentType)
324		if err != nil {
325			return filename
326		}
327	
328		extensions, err := mime.ExtensionsByType(mediaType)
329		if err != nil || len(extensions) == 0 {
330			return filename
331		}
332	
333		ext := path.Ext(filename)
334		if len(ext) > 1 && len(ext) <= 20 {
335			return filename
336		}
337		return filename + extensions[0]
338	}
