381	// decodeFilenameParam decodes filename parameter value
382	// Handles HTML entities, MIME encoded-word, URL encoding, and GBK encoding fallback
383	func decodeFilenameParam(filename string) string {
384		// First, unescape HTML entities (e.g., &amp; -> &, &lt; -> <, &gt; -> >)
385		// This must be done before other decoding to handle cases where servers
386		// HTML-encode special characters in filenames
387		filename = unescapeHTMLEntities(filename)
388	
389		// Handle RFC 2047 encoded word (=?charset?encoding?text?=)
390		if strings.HasPrefix(filename, "=?") {
391			decoder := new(mime.WordDecoder)
392			normalizedFilename := strings.Replace(filename, "UTF8", "UTF-8", 1)
393			if decoded, err := decoder.Decode(normalizedFilename); err == nil {
394				return decoded
395			}
396		}
397	
398		// Try URL decoding - use PathUnescape for filenames to handle %2B correctly
399		decoded := util.TryUrlPathUnescape(filename)
400	
401		// If not valid UTF-8, try GBK decoding (common for Chinese websites)
402		if !utf8.ValidString(decoded) {
403			if gbkDecoded := tryDecodeGBK(decoded); gbkDecoded != "" {
404				return gbkDecoded
405			}
406		}
407	
408		return decoded
409	}
