431	// tryDecodeGBK attempts to decode string as GBK encoding
432	func tryDecodeGBK(s string) string {
433		if len(s) == 0 {
434			return ""
435		}
436	
437		decoder := simplifiedchinese.GBK.NewDecoder()
438		decoded, err := decoder.Bytes([]byte(s))
439		if err != nil {
440			return ""
441		}
442		result := string(decoded)
443		if utf8.ValidString(result) {
444			return result
445		}
446		return ""
447	}
