135		)
136		headers := http.Header{}
137		if req.Extra == nil {
138			method = http.MethodGet
139		} else {
140			extra := req.Extra.(*fhttp.ReqExtra)
141			if extra.Method != "" {
142				method = extra.Method
143			} else {
144				method = http.MethodGet
145			}
146			if len(extra.Header) > 0 {
147				for k, v := range extra.Header {
148					headers.Set(k, strings.TrimSpace(v))
149				}
150			}
151			if extra.Body != "" {
152				body = bytes.NewBufferString(extra.Body)
153			}
154		}
155		if _, ok := headers[base.HttpHeaderUserAgent]; !ok {
156			headers.Set(base.HttpHeaderUserAgent, strings.TrimSpace(f.config.UserAgent))
157		}
158	
159		if ctx != nil {
160			httpReq, err = http.NewRequestWithContext(ctx, method, reqUrl, body)
161		} else {
162			httpReq, err = http.NewRequest(method, reqUrl, body)
163		}
164		if err != nil {
165			return
166		}
167		httpReq.Header = headers
168		if host := headers.Get(base.HttpHeaderHost); host != "" {
169			httpReq.Host = host
170		}
171		return httpReq, nil
172	}
