174	// updateRedirectURL updates the redirect URL from the response.
175	// This is called when a request using the original URL succeeds after the redirect URL expired.
176	func (f *Fetcher) updateRedirectURL(url string) {
177		f.redirectLock.Lock()
178		f.redirectURL = url
179		f.redirectLock.Unlock()
180	}
