182	// hasRedirectURL checks if a redirect URL exists and is different from the original URL.
183	func (f *Fetcher) hasRedirectURL() bool {
184		f.redirectLock.Lock()
185		defer f.redirectLock.Unlock()
186		return f.redirectURL != "" && f.redirectURL != f.meta.Req.URL
