189	// isRedirectExpiredError checks if the error indicates that the redirect URL may have expired.
190	// This includes 403 (Forbidden), 401 (Unauthorized), 410 (Gone), and network errors.
191	func isRedirectExpiredError(err error) bool {
192		if err == nil {
193			return false
194		}
195	
196		// Check for specific HTTP error codes that might indicate URL expiration
197		if re := extractRequestError(err); re != nil {
198			switch re.Code {
199			case 401, 403, 404, 410:
200				return true
201			}
202		}
203	
204		return false
205	}
