207	// tryFallbackToOriginalURL attempts to make a request using the original URL
208	// when the redirect URL has expired. Returns the response if successful.
209	func (f *Fetcher) tryFallbackToOriginalURL(ctx context.Context, client *http.Client, rangeStart int64, rangeEnd *int64, rangeRequested bool, ifRange string) (*http.Response, error) {
210		httpReq, err := f.buildRequestWithOriginalURL(ctx, f.meta.Req)
211		if err != nil {
212			return nil, err
213		}
214	
215		if rangeRequested {
216			httpReq.Header.Set(base.HttpHeaderRange, formatRangeHeader(rangeStart, rangeEnd))
217			if ifRange != "" {
218				httpReq.Header.Set(base.HttpHeaderIfRange, ifRange)
219			}
220		}
221	
222		resp, err := client.Do(httpReq)
223		if err != nil {
224			return nil, err
225		}
226	
227		if resp.StatusCode != base.HttpCodeOK && resp.StatusCode != base.HttpCodePartialContent {
228			resp.Body.Close()
229			return nil, NewRequestError(resp.StatusCode)
230		}
231	
232		return resp, nil
233	}
