235	func formatRangeHeader(start int64, end *int64) string {
236		if end == nil {
237			return fmt.Sprintf("bytes=%d-", start)
238		}
239		return fmt.Sprintf(base.HttpHeaderRangeFormat, start, *end)
240	}
