242	// buildClient creates an HTTP client with the default connection timeout.
243	// Used for resolve phase where we don't have connection time data yet.
244	func (f *Fetcher) buildClient() *http.Client {
245		return f.buildClientWithTimeout(connectTimeout)
246	}
