248	// buildFastFailClient creates an HTTP client with fast-fail timeout.
249	// Uses max(minFastFailTimeout, maxConnTime) for fast-fail retry during download phase.
250	func (f *Fetcher) buildFastFailClient() *http.Client {
251		maxConn := f.maxConnTime.Load()
252		if maxConn == 0 {
253			// No successful connection yet, use default timeout
254			return f.buildClientWithTimeout(connectTimeout)
255		}
256	
257		timeout := maxConn
258		if timeout >= minFastFailTimeout {
259			// If greater than minFastFailTimeout, increase by 50% for safety margin
260			timeout = int64(float64(timeout) * 1.5)
261		} else {
262			timeout = minFastFailTimeout
263		}
264		return f.buildClientWithTimeout(time.Duration(timeout))
265	}
