267	// buildClientWithTimeout creates an HTTP client with the specified connection timeout.
268	func (f *Fetcher) buildClientWithTimeout(timeout time.Duration) *http.Client {
269		jar, _ := cookiejar.New(nil)
270		client, err := httpclient.NewClient(httpclient.Options{
271			Client: httpclient.ClientOptions{
272				Jar: jar,
273			},
274			Transport: httpclient.TransportOptions{
275				DialContext: (&net.Dialer{
276					Timeout: timeout,
277				}).DialContext,
278				Proxy: f.ctl.GetProxy(f.meta.Req.Proxy),
279				TLSClientConfig: &tls.Config{
280					InsecureSkipVerify: f.meta.Req.SkipVerifyCert,
281				},
282				TLSHandshakeTimeout: timeout,
283			},
284			Impersonation: httpclient.ImpersonationOptions{
285				Mode:    httpclient.ImpersonationAuto,
286				Session: f.impersonationSession,
287			},
288		})
289		if err != nil {
290			panic(fmt.Sprintf("build HTTP client: %v", err))
291		}
292		return client
293	}
