295	// ============================================================================
296	// Filename Parsing
297	// ============================================================================
298	
299	// parseFilename extracts filename from Content-Disposition header
300	func parseFilename(contentDisposition string) string {
301		// Try RFC 5987 extended notation first (filename*=)
302		if filename := parseFilenameExtended(contentDisposition); filename != "" {
303			return filename
304		}
305	
306		// Try standard MIME parsing
307		_, params, err := mime.ParseMediaType(contentDisposition)
308		if err == nil {
309			if filename := params["filename"]; filename != "" {
310				return decodeFilenameParam(filename)
311			}
312		}
313	
314		// Fallback to manual parsing
315		return parseFilenameFallback(contentDisposition)
316	}
317	
318	// appendFilenameExtension adds a MIME-derived extension when the resolved
319	// filename has no usable extension. Some image hosts use opaque path segments
320	// that look like extensions, even though the response Content-Type is the
321	// only reliable source for the file type.
322	func appendFilenameExtension(filename, contentType string) string {
323		mediaType, _, err := mime.ParseMediaType(contentType)
324		if err != nil {
325			return filename
326		}
327	
328		extensions, err := mime.ExtensionsByType(mediaType)
329		if err != nil || len(extensions) == 0 {
330			return filename
331		}
332	
333		ext := path.Ext(filename)
334		if len(ext) > 1 && len(ext) <= 20 {
335			return filename
336		}
337		return filename + extensions[0]
338	}
339	
340	// parseFilenameExtended handles RFC 5987 extended notation (filename*=)
341	// Format: filename*=charset'language'value (e.g., UTF-8”%E6%B5%8B%E8%AF%95.zip)
342	func parseFilenameExtended(cd string) string {
343		lower := strings.ToLower(cd)
344		idx := strings.Index(lower, "filename*=")
345		if idx == -1 {
346			return ""
347		}
348	
349		value := cd[idx+len("filename*="):]
350	
351		// Find the end of the value using proper quote handling
352		endIdx := findParamValueEnd(value)
353		if endIdx != -1 {
354			value = value[:endIdx]
355		}
356		value = strings.TrimSpace(value)
357	
358		// Try charset''encoded format (e.g., UTF-8''%E4%B8%AD%E6%96%87.txt)
359		parts := strings.SplitN(value, "''", 2)
360		if len(parts) == 2 {
361			// Use PathUnescape to handle %2B correctly (should decode to +, not space)
362			decoded, err := url.PathUnescape(parts[1])
363			if err == nil {
364				return decoded
365			}
366		}
367	
368		// Try charset'language'encoded format
369		parts = strings.SplitN(value, "'", 3)
370		if len(parts) >= 3 {
371			// Use PathUnescape to handle %2B correctly (should decode to +, not space)
372			decoded, err := url.PathUnescape(parts[2])
373			if err == nil {
374				return decoded
375			}
376		}
377	
378		return ""
379	}
380	
381	// decodeFilenameParam decodes filename parameter value
382	// Handles HTML entities, MIME encoded-word, URL encoding, and GBK encoding fallback
383	func decodeFilenameParam(filename string) string {
384		// First, unescape HTML entities (e.g., &amp; -> &, &lt; -> <, &gt; -> >)
385		// This must be done before other decoding to handle cases where servers
386		// HTML-encode special characters in filenames
387		filename = unescapeHTMLEntities(filename)
388	
389		// Handle RFC 2047 encoded word (=?charset?encoding?text?=)
390		if strings.HasPrefix(filename, "=?") {
391			decoder := new(mime.WordDecoder)
392			normalizedFilename := strings.Replace(filename, "UTF8", "UTF-8", 1)
393			if decoded, err := decoder.Decode(normalizedFilename); err == nil {
394				return decoded
395			}
396		}
397	
398		// Try URL decoding - use PathUnescape for filenames to handle %2B correctly
399		decoded := util.TryUrlPathUnescape(filename)
400	
401		// If not valid UTF-8, try GBK decoding (common for Chinese websites)
402		if !utf8.ValidString(decoded) {
403			if gbkDecoded := tryDecodeGBK(decoded); gbkDecoded != "" {
404				return gbkDecoded
405			}
406		}
407	
408		return decoded
409	}
410	
411	// unescapeHTMLEntities unescapes common HTML entities in filenames
412	// This handles cases where servers HTML-encode special characters like & to &amp;
413	func unescapeHTMLEntities(s string) string {
414		// Common HTML entities that might appear in filenames
415		replacements := map[string]string{
416			"&amp;":  "&",
417			"&lt;":   "<",
418			"&gt;":   ">",
419			"&quot;": "\"",
420			"&#39;":  "'",
421			"&apos;": "'",
422		}
423	
424		result := s
425		for entity, char := range replacements {
426			result = strings.ReplaceAll(result, entity, char)
427		}
428		return result
429	}
430	
431	// tryDecodeGBK attempts to decode string as GBK encoding
432	func tryDecodeGBK(s string) string {
433		if len(s) == 0 {
434			return ""
435		}
436	
437		decoder := simplifiedchinese.GBK.NewDecoder()
438		decoded, err := decoder.Bytes([]byte(s))
439		if err != nil {
440			return ""
441		}
442		result := string(decoded)
443		if utf8.ValidString(result) {
444			return result
445		}
446		return ""
447	}
448	
449	// parseFilenameFallback is a fallback parser for non-standard Content-Disposition
450	func parseFilenameFallback(cd string) string {
451		lower := strings.ToLower(cd)
452		idx := strings.Index(lower, "filename=")
453		if idx == -1 {
454			return ""
455		}
456	
457		value := cd[idx+len("filename="):]
458	
459		// Find the end of the value using proper quote handling
460		endIdx := findParamValueEnd(value)
461		if endIdx != -1 {
462			value = value[:endIdx]
463		}
464		value = strings.TrimSpace(value)
465	
466		// Remove surrounding quotes
467		if len(value) >= 2 {
468			if (value[0] == '"' && value[len(value)-1] == '"') ||
469				(value[0] == '\'' && value[len(value)-1] == '\'') {
470				value = value[1 : len(value)-1]
471			}
472		}
473	
474		return decodeFilenameParam(value)
475	}
476	
477	// findParamValueEnd finds the end position of a parameter value in a Content-Disposition header.
478	// It correctly handles quoted values where semicolons inside quotes should not be treated as delimiters.
479	// It also handles HTML entities in unquoted values (e.g., &amp; should not be split at the semicolon).
480	// Returns the end index (exclusive) of the value, or -1 if it extends to the end of the string.
481	func findParamValueEnd(value string) int {
482		value = strings.TrimSpace(value)
483		if len(value) == 0 {
484			return 0
485		}
486	
487		// If the value starts with a quote, find the matching closing quote
488		if value[0] == '"' || value[0] == '\'' {
489			quote := value[0]
490			// Find the closing quote, handling escaped quotes
491			for i := 1; i < len(value); i++ {
492				if value[i] == quote {
493					// Check if it's escaped
494					if i > 0 && value[i-1] == '\\' {
495						continue
496					}
497					// Found closing quote, now look for ; after it
498					remaining := value[i+1:]
499					if semiIdx := strings.Index(remaining, ";"); semiIdx != -1 {
500						return i + 1 + semiIdx
501					}
502					return -1 // No semicolon after closing quote
503				}
504			}
505			// No closing quote found, treat rest of string as value
506			return -1
507		}
508	
509		// Unquoted value - find the next semicolon that's not part of an HTML entity
510		// HTML entities have the pattern &...;  (e.g., &amp; &lt; &gt; &quot; &#39;)
511		for i := 0; i < len(value); i++ {
512			if value[i] == ';' {
513				// Check if this semicolon is part of an HTML entity
514				// Look backwards for an & character
515				isEntity := false
516				if i > 0 {
517					// Look for & before this semicolon (within reasonable distance, max 10 chars)
518					for j := i - 1; j >= 0 && j >= i-10; j-- {
519						if value[j] == '&' {
520							// Found &, this semicolon might be part of an HTML entity
521							// Check if there are only alphanumeric or # between & and ;
522							entityChars := value[j+1 : i]
523							if len(entityChars) > 0 && isValidHTMLEntityChars(entityChars) {
524								isEntity = true
525							}
526							break
527						}
528						// If we hit whitespace or another special char, stop looking
529						if value[j] == ' ' || value[j] == '"' || value[j] == '\'' {
530							break
531						}
532					}
533				}
534	
535				if !isEntity {
536					return i
537				}
538			}
539		}
540		return -1 // No semicolon, extends to end
541	}
542	
543	// isValidHTMLEntityChars checks if a string contains only valid HTML entity characters
544	// (alphanumeric and #, typically for entities like &amp; &lt; &#39; etc.)
545	func isValidHTMLEntityChars(s string) bool {
546		if len(s) == 0 {
547			return false
548		}
549		for _, c := range s {
550			if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '#') {
551				return false
552			}
553		}
554		return true
555	}
