1295	func testFetcherUnknownSizeRange(t *testing.T, hint int64) {
1296		const resolveETag = `"unknown-size-v1"`
1297		payload := make([]byte, 4*1024*1024)
1298		for i := range payload {
1299			payload[i] = byte((i*11 + 7) % 251)
1300		}
1301	
1302		var openEndedRequests atomic.Int32
1303		var rangeRequests atomic.Int32
1304		server := httptest.NewServer(gohttp.HandlerFunc(func(w gohttp.ResponseWriter, r *gohttp.Request) {
1305			rangeHeader := r.Header.Get(base.HttpHeaderRange)
1306			w.Header().Set(base.HttpHeaderAcceptRanges, base.HttpHeaderBytes)
1307			w.Header().Set(base.HttpHeaderETag, resolveETag)
1308			if rangeHeader == "" {
1309				w.WriteHeader(gohttp.StatusOK)
1310				w.(gohttp.Flusher).Flush()
1311				for offset := 0; offset < len(payload); offset += 8 * 1024 {
1312					end := min(offset+8*1024, len(payload))
1313					if _, err := w.Write(payload[offset:end]); err != nil {
1314						return
1315					}
1316					w.(gohttp.Flusher).Flush()
1317					time.Sleep(2 * time.Millisecond)
1318				}
1319				return
1320			}
1321	
1322			rangeRequests.Add(1)
1323			if got := r.Header.Get(base.HttpHeaderIfRange); got != resolveETag {
1324				t.Errorf("If-Range = %q, want %q", got, resolveETag)
1325			}
1326			var start, end int64
1327			if strings.HasSuffix(rangeHeader, "-") {
1328				openEndedRequests.Add(1)
1329				if _, err := fmt.Sscanf(rangeHeader, "bytes=%d-", &start); err != nil {
1330					t.Errorf("parse open-ended Range %q: %v", rangeHeader, err)
1331					w.WriteHeader(gohttp.StatusBadRequest)
1332					return
1333				}
1334				end = int64(len(payload) - 1)
1335			} else if _, err := fmt.Sscanf(rangeHeader, "bytes=%d-%d", &start, &end); err != nil {
1336				t.Errorf("parse bounded Range %q: %v", rangeHeader, err)
1337				w.WriteHeader(gohttp.StatusBadRequest)
1338				return
1339			}
1340			if start > end {
1341				w.Header().Set(base.HttpHeaderContentRange, fmt.Sprintf("bytes */%d", len(payload)))
1342				w.WriteHeader(gohttp.StatusRequestedRangeNotSatisfiable)
1343				return
1344			}
1345			w.Header().Set(base.HttpHeaderContentRange, fmt.Sprintf("bytes %d-%d/%d", start, end, len(payload)))
1346			w.Header().Set(base.HttpHeaderContentLength, fmt.Sprintf("%d", end-start+1))
1347			w.WriteHeader(gohttp.StatusPartialContent)
1348			for offset := start; offset <= end; offset += 8 * 1024 {
1349				chunkEnd := min(offset+8*1024, end+1)
1350				if _, err := w.Write(payload[offset:chunkEnd]); err != nil {
1351					return
1352				}
1353				w.(gohttp.Flusher).Flush()
1354				time.Sleep(time.Millisecond)
1355			}
1356		}))
1357		defer server.Close()
1358	
1359		f := buildFetcher()
1360		f.Meta().Opts = &base.Options{
1361			Size: hint,
1362			Path: t.TempDir(),
1363			Name: "unknown-size-range.data",
1364			Extra: &http.OptsExtra{
1365				Connections: 4,
1366			},
1367		}
1368		if err := f.Resolve(&base.Request{URL: server.URL + "/unknown-size-range.data"}); err != nil {
1369			t.Fatal(err)
1370		}
1371		defer f.Close()
1372	
1373		if f.meta.Res.Size != hint || f.hasKnownSize() || !f.meta.Res.Range {
1374			t.Fatalf("resolved resource = %+v, want unknown size with Range support", f.meta.Res)
1375		}
1376		if err := f.Start(); err != nil {
